void TextureAsset::Impl::PreLoad(const char *name)
{
	char path[260];
	strcpy(path, name);

	// Probe the image formats in order of preference; a .jpg carries its
	// alpha in a .png of the same name.
	char *ext = strrchr(path, '.');
	if (ext != NULL) {
		strcpy(ext, ".dds");
		m_file = GetGameFile(path);
		if (m_file == NULL) {
			strcpy(ext, ".tga");
			m_file = GetGameFile(path);
			if (m_file == NULL) {
				strcpy(ext, ".jpg");
				m_file = GetGameFile(path);
				if (m_file != NULL) {
					strcpy(ext, ".png");
					m_alphaFile = GetGameFile(path);
				}
			}
		}
	}

	if (m_file != NULL)
		m_file->deleteOnClose();
	if (m_alphaFile != NULL)
		m_alphaFile->deleteOnClose();
}

// FUNCTION: BFME2 0x0013132D size=75 name=?rva0013132D@Rva0013132DTarget@@QAEXXZ evidence=?:placeholder tier=B hypothesis:K
void TextureAsset::Impl::Load(void)
{
	if (m_file) {
		m_fileSize = m_file->size();
		m_fileData = m_file->readEntireAndClose();
		m_file = NULL;
		if (m_alphaFile) {
			m_alphaSize = m_alphaFile->size();
			m_alphaData = m_alphaFile->readEntireAndClose();
			m_alphaFile = NULL;
		}
		else {
			m_alphaSize = 0;
			m_alphaData = 0;
		}
	}
}


