	case WW3D_FORMAT_A4L4:
	case WW3D_FORMAT_DXT2:
	case WW3D_FORMAT_DXT3:
	case WW3D_FORMAT_DXT4:
	case WW3D_FORMAT_DXT5:
		bits = 8;
		break;
	case WW3D_FORMAT_DXT1:
